// DEMO SEED — current month ke liye verified work entries
// Purane mock entries (2024-01) fixed date ki wajah se reports
// the "current month" filter always showed empty. These entries
// are generated dynamically around "today", so reports
// always stays populated with demo data — no matter when the app is opened.
// ============================================================
(function seedCurrentMonthDemoEntries() {
    const now = new Date();
    const fmt = (d) => toLocalYMD(d);
    const mk = (daysAgo, workerId, workerName, staffId, line, styleId, styleName, operationId, operation, pieces, pieceRate) => {
        const d = new Date(now);
        d.setDate(d.getDate() - daysAgo);
        return {
            companyId: "c1", id: `demo_cm_${workerId}_${daysAgo}`, date: fmt(d),
            workerId, styleId, operationId, workerName, staffId, styleName, operation,
            pieces, pieceRate, amount: calculateEntryAmount(pieces, pieceRate), line, status: "approved",
        };
    };
    MOCK_DB.workEntries.push(mk(1, "w1", "Sandeep Shing", "SANDEEP-7890", "Stitching", "s1", "Men's Slim Fit Jeans", "op2", "Inseam fitop", 120, 1.70), mk(2, "w1", "Sandeep Shing", "SANDEEP-7890", "Stitching", "s2", "Women's Skinny Jeans", "op4", "Side stitch", 110, 1.00), mk(3, "w2", "Parmod Kumar", "PARMOD-7899", "Stitching", "s1", "Men's Slim Fit Jeans", "op6", "Bealt atteched", 100, 1.50), mk(4, "w2", "Parmod Kumar", "PARMOD-7899", "Stitching", "s4", "Denim Jeans", "op5", "Round stitching", 75, 1.00), mk(2, "w9", "Sanjeev Gupta", "SANJEEV-7892", "Stitching", "s1", "Men's Slim Fit Jeans", "op7", "Thooka", 80, 2.00), mk(5, "w7", "Balkrishn Shing", "BALKRISHN-7894", "Stitching", "s3", "Kids Denim Jeans", "op3", "Five thread", 130, 1.50), mk(1, "w7", "Balkrishn Shing", "BALKRISHN-7894", "Stitching", "s3", "Kids Denim Jeans", "op3", "Five thread", 150, 1.50), mk(6, "w5", "Alok Kumar", "ALOK-7896", "Stitching", "s3", "Kids Denim Jeans", "op4", "Side stitch", 95, 1.00), mk(3, "w5", "Alok Kumar", "ALOK-7896", "Stitching", "s4", "Denim Jeans", "op4", "Side stitch", 60, 1.00));
})();
// ============================================================
// PERSISTENCE — data browser ke localStorage mein save hota hai, refresh / app band karne par bhi bana rehta hai.
// Do keys: STATE (App ki shared state) aur MOCK (MOCK_DB ke tables jo seedhe mutate hote hain).
// localStorage na mile (private mode / sandbox) to chupchaap in-memory chalta hai. Reset: console mein twResetData()
// ============================================================
const TWE_STATE_KEY = "twe_state_v7"; // v7: naye 9 Stitching tailors (purana v1–v6 state ignore hota hai)
const TWE_MOCK_KEY = "twe_mock_v2"; // v2: naye Jeans operations (purana v1 ignore hota hai)
const twStore = {
    get(k) { try {
        return window.localStorage.getItem(k);
    }
    catch (e) {
        return null;
    } },
    set(k, v) { try {
        window.localStorage.setItem(k, v);
        return true;
    }
    catch (e) {
        return false;
    } },
    del(k) { try {
        window.localStorage.removeItem(k);
    }
    catch (e) { } },
};
["twe_state_v3", "twe_state_v4", "twe_state_v5", "twe_state_v6", "twe_mock_v1"].forEach(k => twStore.del(k)); // purana saved data hata do — naya mock data dikhe
let _lastMockJson = null, _lastStateJson = null; // PERF: unchanged payload ko dobara localStorage mein nahi likhte
const saveMockParts = () => {
    try {
        const json = JSON.stringify({ v: 1, operations: MOCK_DB.operations, companies: MOCK_DB.companies, companyOwners: MOCK_DB.companyOwners, tailorAccounts: MOCK_DB.tailorAccounts, idRegistry: MOCK_DB.idRegistry, invitations: MOCK_DB.invitations });
        if (json === _lastMockJson)
            return true;
        const ok = twStore.set(TWE_MOCK_KEY, json);
        if (ok === true)
            _lastMockJson = json;
        return ok === true;
    }
    catch (e) {
        console.error("TWE mock data save failed", e);
        return false;
    }
};
const PERSISTED = (() => {
    if (typeof window === "undefined")
        return null;
    try {
        const mockRaw = twStore.get(TWE_MOCK_KEY);
        if (mockRaw) {
            const m = twSafeParse(mockRaw);
            if (m && m.v === 1) {
                ["operations", "companies", "companyOwners", "tailorAccounts", "invitations"].forEach(k => {
                    if (Array.isArray(m[k]))
                        MOCK_DB[k].splice(0, MOCK_DB[k].length, ...m[k]);
                });
                if (m.idRegistry && typeof m.idRegistry === "object") {
                    const r = m.idRegistry;
                    MOCK_DB.idRegistry = { tailor: Number(r.tailor) || 0, company: Number(r.company) || 0, retired: Array.isArray(r.retired) ? r.retired : [], scheme: r.scheme };
                }
            }
        }
        const raw = twStore.get(TWE_STATE_KEY);
        if (!raw)
            return null;
        const d = twSafeParse(raw);
        if (!d || d.v !== 1)
            return null;
        // SECURITY: purane localStorage state mein saved auth user ko kabhi session source mat banao.
        // Data compatibility ke liye baaki demo/application state preserve rahega.
        delete d.user;
        // Workers: MOCK_DB.workers ko bhi saved list se sync rakho (fallback readers ke liye)
        if (Array.isArray(d.workers))
            MOCK_DB.workers.splice(0, MOCK_DB.workers.length, ...d.workers);
        return d;
    }
    catch (e) {
        return null;
    }
})();
// ============================================================
// ACCOUNT & INTERNAL ID SYSTEM
// - Tailor ko "TW000001..." aur Company ko "CO000001..." — dono ki sequence alag-alag.
// - ID system khud banata hai; user ko yaad rakhne ya manually banane ki zaroorat nahi.
// - ID mobile number se bandhi nahi hai: mobile badle to ID wahi rehti hai (changeAccountMobile).
// - Counter sirf aage badhta hai aur deleted accounts ki IDs "retired" list mein jaati hain,
//   isliye delete hui ID dobara kisi ko nahi milti (sabse badi ID delete ho tab bhi).
// NOTE: Ye frontend prototype hai (browser localStorage). Production mein ye backend/database ka kaam hai.
// ============================================================
const ID_PREFIX = { tailor: "TW", company: "CO" };
const idNumOf = (id) => parseInt(String(id || "").replace(/\D/g, ""), 10) || 0;
const nextInternalId = (kind) => {
    const pre = ID_PREFIX[kind];
    const reg = MOCK_DB.idRegistry || (MOCK_DB.idRegistry = { tailor: 0, company: 0, retired: [] });
    const live = kind === "tailor" ? (MOCK_DB.tailorAccounts || []) : (MOCK_DB.companyOwners || []);
    const nums = [reg[kind] || 0, ...live.map(a => idNumOf(a.globalId)), ...(reg.retired || []).filter(x => new RegExp("^" + pre + "\\d{6}$").test(String(x))).map(idNumOf)];
    const n = Math.max(...nums) + 1;
    reg[kind] = n;
    saveMockParts();
    return pre + String(n).padStart(6, "0");
};
// Tailor ID (tailor) = PURA PEHLA NAAM (First Name) + "-" + mobile ke aakhri 4 digit. Doosra naam (Second Name / surname) ID mein nahi aata.
// Jaise First Name "Sunita", Second Name "Devi", mobile 9812345678 -> SUNITA-5678.
// Ek hi first name + last4 do logon ka ho to doosre ko "-2" jaisa suffix milta hai taaki ID kabhi repeat na ho. ID ek baar banti hai — baad mein mobile/naam badle to ID wahi rehti hai.
const makeTailorId = (name, mobile, firstName) => {
    let units = [];
    if (firstName && String(firstName).trim())
        units = String(firstName).toUpperCase().match(/\p{L}\p{M}*/gu) || [];
    if (!units.length)
        for (const tok of String(name || "").trim().toUpperCase().split(/\s+/)) {
            units = tok.match(/\p{L}\p{M}*/gu) || [];
            if (units.length)
                break;
        }
    const letters = units.join("") || "TAYLO";
    const last4 = String(mobile || "").replace(/\D/g, "").slice(-4).padStart(4, "0");
    const base = `${letters}-${last4}`;
    const used = new Set([...(MOCK_DB.tailorAccounts || []).map(a => a && a.globalId), ...(MOCK_DB.workers || []).map(w => w && w.globalId), ...(((MOCK_DB.idRegistry || {}).retired) || [])].filter(Boolean));
    let id = base, n = 1;
    while (used.has(id)) {
        n += 1;
        id = `${base}-${n}`;
    }
    return id;
};
// ============================================================
// COMPANY <-> TAILOR CONNECTION (Invitation flow)
// 1) Company Tailor ke mobile ke last 4 digits se search karti hai
// 2) Tailor ko Company ka naam + Accept / Reject milta hai (Pending / Accepted / Rejected)
// 3) Tailor Accept kare tabhi connection (active worker record) banta hai — uski permission ke bina nahi
// 4) Connection active hone ke baad hi Company kaam allocate / entry kar sakti hai
// Last 4 digits unique pehchaan nahi hain — ek se zyada match par naam + masked mobile se sahi tailor chuna jata hai.
// Connection khatam hone par (worker inactive) purane work records kabhi delete nahi hote; dobara accept par wahi record wapas active hota hai.
// ============================================================
const maskMobile = (m) => { const d = String(m || "").replace(/\D/g, ""); return d.length === 10 ? d.slice(0, 2) + "XXXX" + d.slice(6) : "XXXXXX" + d.slice(-4); };
const emitConnectionChange = (detail = {}) => { try {
    window.dispatchEvent(new CustomEvent("twes-connection-changed", { detail }));
}
catch (_) { } };
const useInviteTick = () => {
    const [t, setT] = useState(0);
    useEffect(() => { const h = () => setT(x => x + 1); window.addEventListener("twes-connection-changed", h); return () => window.removeEventListener("twes-connection-changed", h); }, []);
    return t;
};
const findActiveConnection = (companyId, tailorId) => (MOCK_DB.workers || []).find(w => w.companyId === companyId && w.tailorId === tailorId && w.status === "active") || null;
const findPendingInvite = (companyId, tailorId) => (MOCK_DB.invitations || []).find(i => i.source !== "team" && i.companyId === companyId && i.tailorId === tailorId && i.status === "pending") || null;
const sendInvitation = ({ companyId, tailorId, staffId, designation, lineIds, lineNames }) => {
    const acc = (MOCK_DB.tailorAccounts || []).find(a => a.id === tailorId);
    const company = (MOCK_DB.companies || []).find(c => c.id === companyId);
    if (!acc || !company)
        return { ok: false, error: "Tailor ya company nahi mili." };
    if (findActiveConnection(companyId, tailorId))
        return { ok: false, error: `${acc.name} pehle se aapki company se connected hai.` };
    if (findPendingInvite(companyId, tailorId))
        return { ok: false, error: `${acc.name} ko invitation pehle se bheji hui hai (Pending).` };
    const inv = {
        id: uid("inv_"), companyId, companyName: company.name,
        tailorId, tailorGlobalId: acc.globalId, tailorName: acc.name, maskedMobile: maskMobile(acc.mobile),
        staffId: acc.globalId, designation: String(designation || "").trim() || "Tailor",
        lineIds: Array.isArray(lineIds) ? lineIds : [], lineNames: Array.isArray(lineNames) ? lineNames : [],
        status: "pending", createdAt: new Date().toISOString(), respondedAt: null,
    };
    MOCK_DB.invitations.push(inv);
    saveMockParts();
    emitConnectionChange();
    return { ok: true, invitation: inv };
};
// Tailor ka jawab. Accept par hi connection (active worker record) banta hai.
const respondToInvitation = (invId, tailorId, accept) => {
    const inv = (MOCK_DB.invitations || []).find(i => i.id === invId && i.tailorId === tailorId && i.source !== "team");
    if (!inv)
        return { ok: false, error: "Invitation nahi mili." };
    if (inv.status !== "pending")
        return { ok: false, error: "Is invitation par pehle hi jawab ho chuka hai." };
    const now = new Date().toISOString();
    if (!accept) {
        inv.status = "rejected";
        inv.respondedAt = now;
        saveMockParts();
        emitConnectionChange();
        return { ok: true, status: "rejected" };
    }
    const acc = (MOCK_DB.tailorAccounts || []).find(a => a.id === tailorId);
    const company = (MOCK_DB.companies || []).find(c => c.id === inv.companyId);
    if (!acc || !company)
        return { ok: false, error: "Account ya company nahi mili." };
    if (findActiveConnection(inv.companyId, tailorId))
        return { ok: false, error: "Aap is company se pehle se connected ho." }; // duplicate active connection nahi banega
    const companyWorkers = (MOCK_DB.workers || []).filter(w => w.companyId === inv.companyId);
    let w = companyWorkers.find(x => x.tailorId === tailorId); // pehle ka (inactive) record — purani history isi se judi hai
    if (w) {
        Object.assign(w, { status: "active", name: acc.name, mobile: acc.mobile, globalId: acc.globalId, staffId: acc.globalId, garmentTypes: acc.garmentTypes || w.garmentTypes || [] });
    }
    else {
        w = {
            companyId: inv.companyId, id: uid("w_"), name: acc.name, staffId: acc.globalId, mobile: acc.mobile, // ek hi ID: Tailor ID
            designation: inv.designation || "Tailor", line: inv.lineNames?.[0] || "", lineId: inv.lineIds?.[0] || "",
            joinDate: toLocalYMD(), status: "active", tailorId: acc.id, globalId: acc.globalId, garmentTypes: acc.garmentTypes || [],
        };
        MOCK_DB.workers.push(w);
    }
    inv.status = "accepted";
    inv.respondedAt = now;
    inv.workerId = w.id;
    saveMockParts();
    emitConnectionChange({ workerId: w.id, lineIds: inv.lineIds || [] }); // App workers + department enrollment sync
    return { ok: true, status: "accepted", worker: w };
};
// ADMIN khud tailor add/register kare to approval ki zaroorat nahi — seedha connection (active worker + department enrollment).
// Manager add/register kare to wahi purana sendInvitation chalta hai (request admin ki Requests tab mein approve hoti hai).
const connectTailorDirect = ({ companyId, tailorId, designation, lineIds, lineNames, by }) => {
    const r = sendInvitation({ companyId, tailorId, designation, lineIds, lineNames });
    if (!r.ok)
        return r;
    r.invitation.direct = true;
    r.invitation.approvedBy = by || "admin";
    const a = respondToInvitation(r.invitation.id, tailorId, true);
    return a.ok ? { ok: true, worker: a.worker, invitation: r.invitation } : a;
};
const fmtTimeLeft = (expiresAt) => {
    const ms = new Date(expiresAt).getTime() - Date.now();
    if (!(ms > 0))
        return "0m";
    const h = Math.floor(ms / 3600000), m = Math.floor((ms % 3600000) / 60000);
    return h > 0 ? `${h}h ${m}m` : `${m}m`;
};
// accept = true → member pakka (admin ya tailor, jo pehle kare). reject / expiry → team se hatao + entries reject (App listener sunta hai).
const resolveTeamRequest = (invId, accept, by, reason) => {
    const inv = (MOCK_DB.invitations || []).find(i => i.id === invId && i.source === "team");
    if (!inv)
        return { ok: false, error: "Request nahi mili." };
    if (inv.status !== "pending")
        return { ok: false, error: "Is request par pehle hi jawab ho chuka hai." };
    inv.status = accept ? "accepted" : "rejected";
    inv.respondedAt = new Date().toISOString();
    inv.respondedBy = by || "";
    if (!accept && reason)
        inv.reason = reason;
    saveMockParts();
    emitConnectionChange(accept ? {} : { teamRemove: { companyId: inv.companyId, workerId: inv.workerId, lineId: inv.lineIds[0], lineName: inv.lineNames[0], since: inv.createdAt } });
    return { ok: true, status: inv.status };
};
const sweepTeamRequests = () => {
    const now = Date.now();
    (MOCK_DB.invitations || []).filter(i => i.source === "team" && i.status === "pending" && new Date(i.expiresAt).getTime() <= now)
        .forEach(i => resolveTeamRequest(i.id, false, "system", "expired"));
};
