// EK HI ID: har tailor/worker ki pehchaan sirf Tailor ID (globalId) hai = pura pehla naam (First Name) + "-" + mobile ke last 4 digit.
// Purani IDs (Staff ID KE0001 / TW000001 / naam ke 4 akshar wali) ek baar naye ID par badal di jaati hain (scheme flag se);
// worker.staffId field wahi Tailor ID rakhti hai (poori app wahi dikhati hai). Purani entries bhi naye ID par sync hoti hain; history delete nahi hoti.
(function unifyWorkerIds() {
    const SCHEME = "firstname-last4-v1";
    const reg = MOCK_DB.idRegistry || (MOCK_DB.idRegistry = { tailor: 0, company: 0, retired: [] });
    const redo = reg.scheme !== SCHEME;
    const byWorker = {}, byCompanyOld = {};
    let changed = false;
    if (redo) {
        (MOCK_DB.tailorAccounts || []).forEach(a => { if (a)
            a.globalId = null; });
        (MOCK_DB.workers || []).forEach(w => { if (w)
            w.globalId = null; });
    }
    (MOCK_DB.tailorAccounts || []).forEach(a => {
        if (!a || a.globalId)
            return;
        a.globalId = makeTailorId(a.name, a.mobile, a.firstName);
        changed = true;
    });
    (MOCK_DB.invitations || []).forEach(i => {
        const acc = i && (MOCK_DB.tailorAccounts || []).find(a => a.id === i.tailorId);
        if (acc && i.tailorGlobalId !== acc.globalId) {
            i.tailorGlobalId = acc.globalId;
            changed = true;
        }
    });
    (MOCK_DB.workers || []).forEach(w => {
        if (!w)
            return;
        const acc = w.tailorId ? (MOCK_DB.tailorAccounts || []).find(a => a.id === w.tailorId) : null;
        const gid = acc ? acc.globalId : (w.globalId || makeTailorId(w.name, w.mobile, w.firstName));
        if (w.globalId !== gid) {
            w.globalId = gid;
            changed = true;
        }
        if (w.staffId !== gid) {
            if (w.staffId)
                byCompanyOld[`${w.companyId}:${w.staffId}`] = gid;
            byWorker[w.id] = gid;
            w.staffId = gid;
            changed = true;
        }
    });
    if (redo) {
        reg.scheme = SCHEME;
        changed = true;
    }
    if (!changed)
        return;
    const arrays = [];
    [MOCK_DB, PERSISTED].forEach(src => { if (src)
        Object.keys(src).forEach(k => { if (Array.isArray(src[k]) && k !== "workers")
            arrays.push(src[k]); }); });
    arrays.forEach(arr => arr.forEach(e => {
        if (!e || typeof e !== "object" || typeof e.staffId !== "string")
            return;
        const gid = (e.workerId && byWorker[e.workerId]) || byCompanyOld[`${e.companyId}:${e.staffId}`];
        if (gid)
            e.staffId = gid;
    }));
    saveMockParts();
})();
