// ============================================================
// COMPANY DATA-ISOLATION HELPER — har operational table ko current
// to scope by the company's companyId. This ensures one company's
// data is never visible to another company.
// ============================================================
const scopedByCompany = (array, companyId) => {
    // SECURITY: missing companyId must NEVER fail open.
    if (!companyId)
        return [];
    return (array || []).filter(item => item?.companyId === companyId);
};
