// Saari companies ki lines (App har render par update karta hai) — manager-mobile uniqueness cross-company check ke liye
const ALL_LINES_REF = { current: [] };
// Department manager mobile validation: same company mein ek number multiple departments par allowed; doosri company par nahi.
const validateManagerMobile = (mob, line) => {
    if (!/^\d{10}$/.test(mob))
        return "10 digit ka mobile number daalo.";
    if ((MOCK_DB.companyOwners || []).some(o => o.mobile === mob))
        return "Ye number company owner ke account ka hai.";
    const other = (ALL_LINES_REF.current || []).find(l => l.id !== line.id && l.managerMobile === mob && l.companyId !== line.companyId);
    if (other)
        return "Ye number kisi aur company mein manager hai — manager sirf ek company mein ho sakta hai.";
    if ((MOCK_DB.workers || []).some(w => w.status === "active" && w.mobile === mob && w.companyId !== line.companyId))
        return "Ye tailor kisi aur company se connected hai — manager sirf ek company mein ho sakta hai.";
    return "";
};
const buildManagerUser = (acc, line) => {
    const c = MOCK_DB.companies.find(x => x.id === line.companyId);
    return stripSecrets({
        id: acc.id, tailorId: acc.id, globalId: acc.globalId, name: acc.name, mobile: acc.mobile,
        role: "manager", companyId: line.companyId, tenantName: c?.name || "", lineId: line.id, line: line.name,
        assignedLineIds: (ALL_LINES_REF.current || []).filter(l => l.companyId === line.companyId && l.managerMobile === acc.mobile).map(l => l.id),
    });
};
