const allocCoversOp = (a, opName) => !a?.comboId || !Array.isArray(a?.comboOps) || !opName || a.comboOps.includes(opName);
// Carry-forward: allocation par per-operation carryIn (pichli cycle se aaya) / carryOut (agli cycle mein gaya) — { [opName]: qty }
// Operation ki effective allocation = allocatedQty + carryIn − carryOut
const allocOpQty = (a, opName) => toNum(a?.allocatedQty) + toNum(a?.carryIn?.[opName]) - toNum(a?.carryOut?.[opName]);
const allocHasCarry = (a) => Object.values(a?.carryIn || {}).some(v => toNum(v) > 0) || Object.values(a?.carryOut || {}).some(v => toNum(v) > 0);
// Carry kis allocation mein gaya: user ne form mein jo department/cycle chuni (carryToId); purani carry (carryToId nahi) ke liye agli cycle, wahi department/combo.
const carryTargetOf = (allocs, a, cycleType) => {
    if (!a)
        return null;
    const list = allocs || [];
    if (a.carryToId && Object.values(a.carryOut || {}).some(v => toNum(v) > 0)) {
        const t = list.find(x => x.id === a.carryToId && x.id !== a.id);
        if (t)
            return t;
    }
    const cyc = getCycleByKey(a.cycleKey);
    const nextCyc = cyc && getCycleForDate(nextDayYMD(cyc.end), cycleType);
    return (nextCyc && list.find(x => x.id !== a.id && x.styleId === a.styleId && isDeptAlloc(x) && x.department === a.department && x.cycleKey === nextCyc.key && x.comboId === a.comboId && sameCompany(x, a.companyId))) || null;
};
// Is allocation (t) mein carry bhejne wali allocations (chuni hui department/cycle se + purani pichli-cycle wali)
const carryOriginsOf = (allocs, t, cycleType) => {
    const list = allocs || [];
    const direct = list.filter(x => x.id !== t.id && x.carryToId === t.id && Object.values(x.carryOut || {}).some(v => toNum(v) > 0));
    const cyc = getCycleByKey(t.cycleKey);
    const prevCyc = cyc && getCycleForDate(prevDayYMD(cyc.start), cycleType);
    const legacy = prevCyc ? list.filter(x => x.id !== t.id && !x.carryToId && x.styleId === t.styleId && isDeptAlloc(x) && x.department === t.department && x.cycleKey === prevCyc.key && x.comboId === t.comboId && sameCompany(x, t.companyId)) : [];
    return [...direct, ...legacy.filter(l => !direct.includes(l))];
};
// Card par dikhne wali allocation qty: carry-forward (aaya/gaya) judne ke baad ki asli qty. Carry na ho to wahi allocatedQty.
