    const garmentTypeNames = _profileGarments;
    const NO_GARMENT_MSG = "Pehle Profile mein Garment Type add karein, phir operation add hoga.";
    // Source of truth MOCK_DB.operations hai (Work Entry, Allocation, Reports sab wahin se padhte hain) —
    // isliye yahan ke add/edit/delete seedha usi list mein hote hain, sirf local copy mein nahi.
    const [ops, setOps] = useState(scopedByCompany(MOCK_DB.operations, user?.companyId));
    const refreshOps = () => setOps(scopedByCompany(MOCK_DB.operations, user?.companyId));
    const deptNames = (sharedLines || []).map(l => l.name);
    const defaultOpLine = deptNames.includes("Stitching") ? "Stitching" : (deptNames[0] || ""); // stitching-only: nayi operation default Stitching line mein
    const [showModal, setShowModal] = useState(false);
    const [editOp, setEditOp] = useState(null);
    const [form, setForm] = useState({ name: "", pieceRate: "", garmentType: garmentTypeNames[0] || "Shirt", line: defaultOpLine });
    const openAdd = () => { if (garmentTypeNames.length === 0) {
        showToast(NO_GARMENT_MSG, "error");
        return;
    } setEditOp(null); setForm({ name: "", pieceRate: "", garmentType: garmentTypeNames[0] || "Shirt", line: defaultOpLine }); setShowModal(true); };
    // Allocation operation-wise nahi hoti (Style + Department + Cycle) — isliye sirf entries dekhte hain
    const isOpUsed = (id) => (sharedEntries || []).some(e => e.operationId === id);
